  @Test
  public void modifiableCollection() {
    ModifiableUnit unit = ModifiableUnit.create();
    unit.getPrices().add(1.0f);
    unit.addPrices(2.0f);

    check(unit.getPrices()).isOf(1.0f, 2.0f);
