  @Test
  public void isAttributesSet() {
    ModifiableCompanion c1 = ModifiableCompanion.create();
    check(!c1.isInitialized());

    check(!c1.arrayIntsIsSet());
    c1.setArrayInts(1);
    check(c1.arrayIntsIsSet());

    check(!c1.arrayStringsIsSet());
    c1.setArrayStrings("a", "b", "c");
    check(c1.arrayStringsIsSet());

    check(c1).asString().isNonEmpty();

    check(!c1.integerIsSet());
    c1.setInteger(1);
    check(c1.integerIsSet());

    check(!c1.stringIsSet());
    c1.setString("_");
    check(c1.stringIsSet());

    check(c1.isInitialized());

    check(c1).asString().isNonEmpty();
  }

  @Test
  public void clear() {
    ModifiableCompanion c1 = ModifiableCompanion.create();
    check(!c1.isInitialized());
    c1.setArrayInts(1);
    c1.setArrayStrings("a", "b", "c");
    c1.setInteger(1);
    c1.setString("_");

    check(c1.stringIsSet());
    check(c1.isInitialized());
    c1.addOrds(1, 2, 3);

    c1.clear();

    check(!c1.isInitialized());
    check(!c1.stringIsSet());
    check(c1.ords()).isEmpty();
  }

  @Test
  public void unset() {
    ModifiableCompanion c1 = ModifiableCompanion.create();
    check(!c1.isInitialized());
    c1.setArrayInts(1);
    c1.setArrayStrings("a", "b", "c");
    c1.setInteger(1);
    c1.setString("_");

    check(c1.stringIsSet());
    check(c1.isInitialized());

    c1.unsetArrayInts();
    c1.unsetString();

    check(!c1.isInitialized());
    check(c1.arrayStringsIsSet());
    check(c1.integerIsSet());
    check(!c1.arrayIntsIsSet());
    check(!c1.stringIsSet());

    c1.unsetArrayStrings();
    c1.unsetInteger();

    check(!c1.isInitialized());
    check(!c1.arrayStringsIsSet());
    check(!c1.integerIsSet());
    check(!c1.arrayIntsIsSet());
    check(!c1.stringIsSet());

    ModifiableStandalone c2 = ModifiableStandalone.create();
    check(!c2.defIsSet());
    check(!c2.def2IsSet());
    check(c2.def()).is(1);
    check(c2.def2()).is(0);

    c2.setDef(2);
    check(c2.defIsSet());
    check(!c2.def2IsSet());
    check(c2.def()).is(2);

    c2.setDef2(3);
    check(c2.defIsSet());
    check(c2.def2IsSet());
    check(c2.def2()).is(3);

    c2.unsetDef();
    check(!c2.defIsSet());
    check(c2.def2IsSet());
    check(c2.def()).is(1);

    c2.unsetDef2();
    check(!c2.defIsSet());
    check(!c2.def2IsSet());
    check(c2.def2()).is(0);
  }

  @Test
  public void mutatingEquals() {
    ModifiableExtra c1 = ModifiableExtra.create();
    ModifiableExtra c2 = ModifiableExtra.create();

